class Solution:
    def getMaxFunctionValue(self, receiver: List[int], k: int) -> int:
        n = len(receiver)
        best = 0
        for i in range(n):
            cur, tot = i, i
            for _ in range(k):
                cur = receiver[cur]
                tot += cur
            best = max(best, tot)
        return best

