class Solution {
public:
    long long getMaxFunctionValue(vector<int>& receiver, long long k) {
        int n = receiver.size();
        int B = 0;
        while ((1LL << B) <= k) B++;
        B = max(B, 1);
        vector<vector<int>> up(B, vector<int>(n));
        vector<vector<long long>> sm(B, vector<long long>(n));
        for (int i = 0; i < n; i++) { up[0][i] = receiver[i]; sm[0][i] = receiver[i]; }
        for (int j = 1; j < B; j++)
            for (int i = 0; i < n; i++) {
                up[j][i] = up[j - 1][up[j - 1][i]];
                sm[j][i] = sm[j - 1][i] + sm[j - 1][up[j - 1][i]];
            }
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int cur = i;
            long long tot = i, kk = k;
            for (int j = 0; kk; j++, kk >>= 1)
                if (kk & 1) { tot += sm[j][cur]; cur = up[j][cur]; }
            ans = max(ans, tot);
        }
        return ans;
    }
};

