class Solution {
    public long getMaxFunctionValue(int[] receiver, long k) {
        int n = receiver.length;
        int B = 1;
        while ((1L << B) <= k) B++;
        int[][] up = new int[B][n];
        long[][] sm = new long[B][n];
        for (int i = 0; i < n; i++) { up[0][i] = receiver[i]; sm[0][i] = receiver[i]; }
        for (int j = 1; j < B; j++)
            for (int i = 0; i < n; i++) {
                up[j][i] = up[j - 1][up[j - 1][i]];
                sm[j][i] = sm[j - 1][i] + sm[j - 1][up[j - 1][i]];
            }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int cur = i;
            long tot = i, kk = k;
            for (int j = 0; kk != 0; j++, kk >>= 1)
                if ((kk & 1) == 1) { tot += sm[j][cur]; cur = up[j][cur]; }
            ans = Math.max(ans, tot);
        }
        return ans;
    }
}

