var getMaxFunctionValue = function(receiver, k) {
    const n = receiver.length;
    let B = 1;
    while ((2 ** B) <= k) B++;
    const up = [receiver.slice()], sm = [receiver.map(Number)];
    for (let j = 1; j < B; j++) {
        const pu = up[j - 1], ps = sm[j - 1];
        up.push(pu.map((v, i) => pu[v]));
        sm.push(ps.map((v, i) => v + ps[pu[i]]));
    }
    let ans = 0;
    for (let i = 0; i < n; i++) {
        let cur = i, tot = BigInt(i), kk = BigInt(k);
        for (let j = 0; kk > 0n; j++, kk >>= 1n)
            if (kk & 1n) { tot += BigInt(sm[j][cur]); cur = up[j][cur]; }
        if (tot > ans) ans = tot;
    }
    return Number(ans);
};
